const bass = new Tone.MonoSynth({
  oscillator: { type: 'square' },
  volume: -4,
  envelope: { attack: 0.01, decay: 0.2, sustain: 0, release: 0.2 },
  filterEnvelope: { attack: 0.01, decay: 0.1, sustain: 0, release: 0.1, baseFrequency: 100, octaves: 3 },
  filter: { type: 'lowpass', Q: 3 },
}).toDestination();

const drive = new Tone.Distortion(0.5).connect(bass.input);

// A representative syncopated pattern
const bassPattern = new Tone.Pattern(function(time, note){
  bass.triggerAttackRelease(note, '16n', time);
}, ['D#2', null, 'D#2', null, null, 'D#2', null, null, 'D#2', null, 'D#2', null, null, 'D#2', null, null], '16n');

